RESET_HANDLER:	; EF03C6
	; Hardware initialization code shared with table_data ROM
	.include "shared/boot_hw_init.s"
	; End of shared boot code (315 bytes)
	ld (SC0MOD), 0x29
	ld (SC0CR), 0x0
	and (BR0CR), 0xcf
	and (BR0CR), 0xf0

LABEL_EF050F:
	ld (DAREG0), 0xff
	ld (DAREG1), 0xff
	ld (DADRV), 0x3
	ld (PECR), 0x20
	ld XSP, 0xc00
	CALR Seems_to_copy_some_data_buffers

LABEL_EF0529:
	call MainCPU_self_test_routines
	call Get_Firmware_Version
	cp L, 0xff
	jr NZ, LABEL_EF054F

We_seem_to_be_running_boot_ROM_code:	; EF0536
	call Some_VGA_setup
	pushw 0x8
	pushw 0x3
	ld XWA, Bitmap_1bit_Please_Wait	; "Please Wait !!"
	ld BC, 0x30
	ld DE, 0x50
	call Draw_FlashMemUpdate_message_bitmap

LABEL_EF054F:
	ld XWA, 0
	ld (SYSTEM_TIMESTAMP), XWA
	ld (0x400), 0x2
	call LABEL_EF1977
	ld (0x400), 0x3
	CALR LABEL_EF078D
	lda XBC, INTET01
	ld A, (XBC)
	and A, 0x8f
	or A, 0x30
	ld (XBC), A
	lda XBC, INTET45
	ld A, (XBC)
	and A, 0xf8
	or A, 0x3
	ld (XBC), A
	CALR Detect_Region_Code
	cpw (0xFFCA), 0x5aa5
	jr Z, LABEL_EF05A2
	lda XDE, 0x66E
	srl XDE, 1
	ld XWA, 0xf980
	ld XBC, 0x1e8000
	call Copy_DE_words_from_XBC_to_XWA

LABEL_EF05A2:
	call LABEL_EF3B05
	bit 0, (PE)	;  Is the optional HD-AE5000 board present?
	jr NZ, LABEL_EF05B5
	CALR Get_Region_Code
	cp L, 4
	call NZ, HDAE5000_Parport_Setup	; if it is present (and this unit was sold in
					; a specific market region), then call the
					; HDAE5000 PPI init code

LABEL_EF05B5:
