; ===========================================================================
; User_didnt_request_flash_mem_update - Main Boot Sequence
; ===========================================================================
; This is the main boot path after power-on self-test and flash update check.
; Initializes Sub-CPU communication, transfers firmware payload, and verifies
; the transfer succeeded. On failure, displays the "ERROR in CPU data
; transmission" dialog (Screen Group 7).
;
; Boot flow:
;   1. Initialize DMA channels for inter-CPU communication
;   2. Send 192KB Sub-CPU firmware payload
;   3. Verify payload integrity (checksum validation)
;   4. Check error flag - if set, display error dialog
;   5. Continue to main UI initialization
;
; Error handling:
;   - If SubCPU_Payload_Verify returns non-zero in HL, boot with error state
;   - Error state (WA=2) displays error dialog via ScreenGroup_Dispatch
;   - Eventually Screen Group 7 "CPU data transmission" error is shown
;
; See also:
;   - SubCPU_Send_Payload - Payload transfer routine
;   - SubCPU_Payload_Verify - Checksum verification
;   - ErrorDialog_CPUTransmissionError - Error dialog widget
; ===========================================================================
User_didnt_request_flash_mem_update:	; EF05E8
	ld A, (0x402)
	extz WA
	CALR LABEL_EF07F3
	ldw (0xFFCA), 0x0
	set 0, (PA)	; Release Sub-CPU from reset
	call SubCPU_Init_DMA_Channels	; Initialize DMA for inter-CPU comm
	ei 0x0
	CALR SubCPU_Send_Payload	; Transfer 192KB Sub-CPU firmware
	CALR SubCPU_Payload_Verify	; Verify payload checksum
	ld WA, 0
	call ScreenGroup_Dispatch	; Display initial boot screen (group 0)
	ei 0x0
	call LABEL_FB76D8
	CALR SubCPU_Payload_GetErrorFlag	; Check if payload transfer failed
	cp HL, 0	; HL=0: success, HL!=0: error
	jr NZ, Boot_PayloadError	; Branch if error occurred
	ld WA, 1	; Success: use screen group 1
	jr Boot_DisplayScreen

; Sub-CPU payload transfer or verification failed
Boot_PayloadError:	; EF061E
	ld WA, 2	; Error: use screen group 2

Boot_DisplayScreen:	; EF0620
	call ScreenGroup_Dispatch	; Display appropriate screen group
	ld (0x400), 0x6
	ld WA, 3
	call ScreenGroup_Dispatch
	ld (0x400), 0x80
	ldw (0xFFD4), 0x0
	ld A, (0x402)
	extz WA
	CALR LABEL_EF07A2
	ld WA, 4
	call Show_ScreenGroup	; Show screen group 4 (may lead to error dialog)
	CALR LABEL_EF0792
	jp MainLoop

LABEL_EF0651:
	ld L, (0x402)
	ret

LABEL_EF0656:
	ld (INTE0AD), 0x0
	ld (INTE45), 0x0
	ld (INTE67), 0x0
	ld (INTE89), 0x0
	ld (INTEAB), 0x0
	ld (INTET01), 0x0
	ld (INTET23), 0x0
	ld (INTET45), 0x0
	ld (INTET67), 0x0
	ld (INTET89), 0x0
	ld (INTETAB), 0x0
	ld (INTES0), 0x0
	ld (INTES1), 0x0
	ld (INTETC01), 0x0
	ld (INTETC23), 0x0
	ld (INTETC45), 0x0
	ld (INTETC67), 0x0
	ret

; ===========================================================================
; SubCPU_Send_Payload - Transfer 192KB Sub-CPU payload from Table Data ROM
; ===========================================================================
; Entry: None (reads from 0xFFFEEF to check if transfer should proceed)
; Exit:  XIZ restored, payload transferred to Sub-CPU RAM
; Notes: Sends the Sub-CPU firmware payload in multiple 64KB chunks:
;        - 0x830000-0x870000 (5 x 64KB) → Sub-CPU 0x050000-0x090000
;        - Additional data from Table Data ROM → Sub-CPU 0x00F000-0x02F000
;        - Final 256 bytes → Sub-CPU 0x000400 (entry point area)
;        Uses E1 bulk transfer protocol via InterCPU_E1_Bulk_Transfer
;        Includes 0x2000 and 0x100000 iteration delay loops for timing
;        Called during boot sequence after SubCPU_Init_DMA_Channels
; ===========================================================================
SubCPU_Send_Payload:
	push XIZ
	cp (0xFFFEEF), 0xff
	jrl NZ, LABEL_EF078B
	ld XIZ, 0

LABEL_EF0696:
	inc 1, XIZ
	cp XIZ, 0x2000
	jr C, LABEL_EF0696
	ld XWA, 0x830000
	ld XBC, 0x10000
	ld XDE, 0x50000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, 0x840000
	ld XBC, 0x10000
	ld XDE, 0x60000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, 0x850000
	ld XBC, 0x10000
	ld XDE, 0x70000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, 0x860000
	ld XBC, 0x10000
	ld XDE, 0x80000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, 0x870000
	ld XBC, 0x10000
	ld XDE, 0x90000
	call InterCPU_E1_Bulk_Transfer
	ld XIZ, TABLE_DATA_ROM__BASE_ADDR
	cp (0xFFFEED), 0xff
	jr NZ, LABEL_EF072A
	ld XIZ, 0x50000
	ld XWA, 0x3e0000
	ld XBC, 0x50000
	call LABEL_EF41E3
	cp HL, 0xffff
	jr NZ, LABEL_EF072A
	ld XIZ, TABLE_DATA_ROM__BASE_ADDR

LABEL_EF072A:
	ldw (0x404), (XIZ + 0x100)
	ld XWA, XIZ
	add XWA, 0x100
	ld XBC, 0x10000
	ld XDE, 0xf000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, XIZ
	add XWA, 0x10100
	ld XBC, 0x10000
	ld XDE, 0x1f000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, XIZ
	add XWA, 0x20100
	ld BC, 0xff00
	ld XDE, 0x2f000
	call InterCPU_E1_Bulk_Transfer
	ld XWA, XIZ
	ld BC, 0x100
	ld XDE, 0x400
	call InterCPU_E1_Bulk_Transfer
	ld XIZ, 0

LABEL_EF0781:
	inc 1, XIZ
	cp XIZ, 0x100000
	jr C, LABEL_EF0781

LABEL_EF078B:
	pop XIZ
	ret

LABEL_EF078D:
	res 7, (0x406)
	ret

LABEL_EF0792:
	set 7, (0x406)
	ret

LABEL_EF0797:
	ldcf 7, (0x406)
	scc C, A
	cp A, 1
	scc Z, HL
	ret

LABEL_EF07A2:
	cp A, 2
	jr NZ, LABEL_EF07C8
	call Get_Firmware_Version
	and L, 0xf
	extz HL
	lda XBC, LED_patterns_indicating_firmware_version
	ld C, (XBC + HL)
	extz BC
	ld WA, 7
	call Set_LEDs
	push XIZ
	call LABEL_FC3ECC
	pop XIZ
	ret

LABEL_EF07C8:
	cp A, 3
	ret NZ
	ld WA, 0xf0
	call LABEL_F994BD
	ret

LABEL_EF07D4:
	ld XWA, 0x9fffc4
	push XWA
	call LABEL_FF09A0
	inc 4, XSP
	ret

LABEL_EF07E1:
	ld HL, (0x404)
	ret

LABEL_EF07E6:
	ld XWA, 0x87fff5
	push XWA
	call LABEL_FF09A0
	inc 4, XSP
	ret

LABEL_EF07F3:
	cpw (0xFFCA), 0x5aa5
	ret Z
	cp A, 1
	ret NZ
	call LABEL_FC54B2
	ei 0x7
	CALR LABEL_EF0656
	ld XBC, 0x400

LABEL_EF080E:
	ld XWA, 0
	ld (XBC+), XWA
	cp XBC, 0x100000
	jr C, LABEL_EF080E
	ld XBC, 0x1e0000

LABEL_EF0820:
	ld XWA, 0
	ld (XBC+), XWA
	cp XBC, 0x200000
	jr C, LABEL_EF0820
	ldw (0xFFCA), 0x5aa5
	jp LABEL_EF050F
LABEL_EF0838:
