	ld (0x815554), XWA
	ld XWA, 0x550055
	ld (0x80AAA8), XWA
	ld XWA, 0x900090
	ld (0x815554), XWA
	ld XWA, (0x800000)
	ld (XSP + 0x4), XWA
	ld XWA, TABLE_DATA_ROM__BASE_ADDR
	ld XIZ, (XWA + 0x4)
	ei 0x0
	ld XWA, (XSP + 0x4)
	cp XWA, 0x10001
	jr Z, LABEL_EF3D5E
	cp XWA, 0x40004
	jr NZ, LABEL_EF3D74

