Draw_FlashMemUpdate_message_bitmap:	; EF5040
	dec 4, XSP
	push IZ
	ld HL, BC
	ld (XSP + 0x2), XWA
	ld IY, HL
	ld IX, DE
	inc 1, IX
	ld IZ, 0

LABEL_EF5050:
	ld WA, IZ
	extz XWA
	DIVW_WA 0x1c	; 28 bytes = 224 pixels de largura da imagem a ser desenhada
	ld WA, QWA
	cp WA, 0
	jr NZ, LABEL_EF5063
	ld IY, HL	; IY = coordanada X do canto esquerdo da imagem a ser desenhada
	dec 1, IX

LABEL_EF5063:
	ld QHL, 0

LABEL_EF5066:
	ld DE, IZ
	extz XDE
	add XDE, (XSP + 0x2)
	lda XWA, 0xE36A	; table of bit masks (equivalent to 1044h on boot "table_data" rom)
	ld BC, QHL
	extz XBC
	add XBC, XWA	; indexing bit masks with value of QHL
	ld A, (XBC)
	and A, (XDE)	; here XDE points at one of the bytes of the image we're drawing and we select the bit we need
	ld QIXL, A
	ld DE, IX
	extz XDE
	lda XBC, OFFSCREEN_BUFFER_1	; aparentemente isso é um buffer offscreen

Set_XWA_to_320_times_XDE:
	ld XWA, XDE
	sll XWA, 2
	add XWA, XDE
	sll XWA, 6
	cp QIXL, 0
	jr Z, LABEL_EF50AA
	ld DE, IY
	inc 1, IY
	extz XDE
	add XWA, XDE
	ld XDE, XBC
	add XDE, XWA
	ld A, (XSP + 0xa)
	ld (XDE), A
	jr LABEL_EF50BB

LABEL_EF50AA:
	ld DE, IY
	inc 1, IY
	extz XDE
	add XWA, XDE	; XWA = 320*y + x
	ld XDE, XBC
	add XDE, XWA	; XDE = offscreen_buffer[320*y + x]
	ld A, (XSP + 0xc)
	ld (XDE), A

LABEL_EF50BB:
	inc 1, QHL
	cp QHL, 0x8
	jr C, LABEL_EF5066
	inc 1, IZ
	cp IZ, 0x268	; 28 bytes (224 pixels/line) * 22 lines = 0268h bytes
	jr C, LABEL_EF5050
	lda XWA, VIDEO_RAM_BASE
	ld DE, 320 * 240 / 2	; 2 pixels per word
	call Copy_DE_words_from_XBC_to_XWA	; <-- "blit-screen"
	pop IZ
	inc 4, XSP
	retd 0x4

;=============================================================================
; VRAM_FillRect - Fill a rectangular region in video RAM with a color
;
; Fills a 12-pixel tall rectangle in video RAM (0x1A0000) with the specified
; color value. Used for clearing or highlighting UI regions.
;
; Input:
;   BC = Y start coordinate (row)
;   WA = X start coordinate (column)
;   E  = Color/pattern value (8-bit, duplicated to 16-bit)
;
; Output:
;   None (VRAM modified)
;
; Clobbers: XIZ, XHL, XWA, XDE, IX, IY
;=============================================================================
VRAM_FillRect:	; EF50DF
	dec 6, XSP
	push XIZ
	ld (XSP + 0x6), E	; Save color value
	ld (XSP + 0x8), WA	; Save X start
	ld IX, BC	; IX = Y start
	ld (XSP + 0x4), BC
	addw (XSP + 0x4), 0xc	; End Y = start + 12
	cp IX, (XSP + 0x4)
	jr NC, VRAM_FillRect_Done

VRAM_FillRect_RowLoop:
	ld IY, (XSP + 0x8)	; IY = X start
	ld BC, IY
	inc 6, BC	; BC = X end (start + 6)
	cp IY, BC
	jr NC, VRAM_FillRect_NextRow

VRAM_FillRect_ColLoop:
	ld DE, IY
	extz XDE
	ld WA, IX
	extz XWA
	ld XHL, XWA
	sll XHL, 2
	add XHL, XWA
	sll XHL, 6
	add XHL, XDE
	srl XHL, 1
	add XHL, XHL
	ld XIZ, 0x1a0000
	add XIZ, XHL
	ld A, (XSP + 0x6)
	extz WA
	ld DE, WA
	sll DE, 8
	or WA, DE
	ld (XIZ), WA
	inc 2, IY	; X += 2 (word increment)
	cp IY, BC
	jr C, VRAM_FillRect_ColLoop

VRAM_FillRect_NextRow:
	inc 1, IX	; Y++
	cp IX, (XSP + 0x4)
	jr C, VRAM_FillRect_RowLoop

VRAM_FillRect_Done:
	pop XIZ
	inc 6, XSP
	ret

